public String createToken(LoginUser loginUser) {
    String token = IdUtils.fastSimpleUUID();          // 生成 __1__
    loginUser.setToken(token);
    refreshToken(loginUser);                          // LoginUser 存 __2__，TTL 30 分钟
    Map<String, Object> claims = new HashMap<>();
    claims.put(Constants.LOGIN_USER_KEY, token);      // JWT 里只放这个索引
    return buildJwt(claims);
}

public void delLoginUser(String token) {
    // 强制下线的实现：删除 __2__ 中的缓存即 __3__ 生效
    redisCache.deleteObject(LOGIN_TOKEN_KEY + token);
}
